-- Add a public reference without changing IDs, accepted snapshots or historical events.
-- Runtime INSERTs use a CSPRNG code; the default keeps existing insert clients compatible.
ALTER TABLE orders ADD COLUMN order_code VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NULL,
  ADD UNIQUE INDEX orders_code_unique(order_code);
CREATE PROCEDURE backfill_order_codes_20261024()
BEGIN
  DECLARE attempts INT DEFAULT 0;
  WHILE EXISTS (SELECT 1 FROM orders WHERE order_code IS NULL) DO
    SET attempts = attempts + 1;
    IF attempts > 20 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order code backfill incomplete'; END IF;
    -- A random collision leaves that row NULL and is retried, never overwrites another code.
    UPDATE IGNORE orders SET order_code = CONCAT('HLF-',SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1)) WHERE order_code IS NULL;
  END WHILE;
END;
CALL backfill_order_codes_20261024();
DROP PROCEDURE backfill_order_codes_20261024;
ALTER TABLE orders MODIFY order_code VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (CONCAT('HLF-',SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1),SUBSTRING('23456789ABCDEFGHJKLMNPQRSTUVWXYZ',1+MOD(ORD(RANDOM_BYTES(1)),32),1))),
  ADD CONSTRAINT orders_code_format CHECK (REGEXP_LIKE(order_code, '^HLF-[2-9A-HJ-NP-Z]{8}$', 'c'));
